/*
 * TURN MESSAGE EMAILS ON OR OFF FOR THE SIGNED-IN ACCOUNT (TASK-L187 §6).
 *
 * The ONLY thing that clears `emailOptOutAt` (L54: never a migration, never a
 * campaign, never the link). Turning it off keeps the FIRST stamp if one is
 * there, so "when did they ask" stays the moment they first asked. No notice
 * gate: stopping mail must work whatever they have or have not accepted.
 */
if (Inputs.userId !== undefined && Inputs.state !== undefined) {
  (async () => {
    try {
      const userId = String(Inputs.userId || '');
      const state = String(Inputs.state || '');
      if (state !== 'on' && state !== 'off') throw new Error('state must be on or off');
      const users = await Noodl.Records.query('_User', { objectId: { equalTo: userId } }, { limit: 2, plain: true });
      if (users.length !== 1) throw new Error(users.length ? 'two accounts' : 'no account');
      const stamp = state === 'on' ? null : users[0].emailOptOutAt || new Date().toISOString();
      await Noodl.Records.save(userId, { emailOptOutAt: stamp }, { className: '_User' });
      Outputs.on = state === 'on';
      Outputs.done();
    } catch (e) {
      console.error('[dbt:setEmailPreference] ' + String((e && e.message) || e) + ' user=' + String(Inputs.userId || '-'));
      Outputs.failed();
    }
  })();
}
